"""Persistent reservation / compilation controller state machine.

Implements the normative operations of PROTOCOL.md version 3.0.0.
"""
from schema import Invalid, parse_command
import compiler


class Lease(object):
    __slots__ = ('owner', 's', 'e', 'env', 'dead', 'dead_kind')

    def __init__(self, owner, s, e, env):
        self.owner = owner
        self.s = s
        self.e = e
        self.env = env
        self.dead = False
        self.dead_kind = None


class Service(object):
    def __init__(self):
        self.loaded = False
        self.n = 0
        self.links = []          # list of (u, v, cap)
        self.cap = []            # current base capacities
        self.rev = 0
        self.now = 0
        self.leases = {}         # id -> Lease (live or dead committed)
        self.load_ids = set()    # ids originating in load
        self.prepares = {}       # id -> dict(payload, base_rev, outcome)
        self.record_order = []   # not required, kept for replay history

    # ---------- helpers ----------
    def live(self):
        return [i for i, l in self.leases.items() if not l.dead and l.e > self.now]

    def used(self, link, t):
        total = 0
        for i, l in self.leases.items():
            if l.dead:
                continue
            if l.s <= t < l.e:
                total += l.env.get(link, 0)
        return total

    def err(self, code):
        return {'status': 'error', 'code': code, 'rev': self.rev}

    def stale(self):
        return {'status': 'stale', 'rev': self.rev}

    # ---------- load ----------
    def do_load(self, n, links, bookings):
        if self.loaded:
            return self.err('ALREADY_LOADED')
        # structural overbooking check only for the first load
        caps = [c for (_, _, c) in links]
        events = set()
        for (_, _, (_, (s, e), env)) in [(b[0], b[1], (b[2], b[2], b[3])) for b in []]:
            pass
        for (bid, owner, (s, e), env) in bookings:
            events.add(s)
            events.add(e)
        times = sorted(events) if events else [0]
        for t in times:
            used = [0] * n if False else [0] * len(links)
            for (bid, owner, (s, e), env) in bookings:
                if s <= t < e:
                    for (l, rate) in env.items():
                        used[l] += rate
            for idx, u in enumerate(used):
                if u > caps[idx]:
                    raise Invalid
        self.loaded = True
        self.n = n
        self.links = links
        self.cap = list(caps)
        self.rev = 0
        self.now = 0
        for (bid, owner, (s, e), env) in bookings:
            lease = Lease(owner, s, e, dict(env))
            self.leases[bid] = lease
            self.load_ids.add(bid)
        return {'status': 'ok', 'rev': 0, 'now': 0}

    # ---------- audit ----------
    def do_audit(self, ticks):
        for t in ticks:
            if t < self.now:
                return self.err('TIME')
        samples = []
        for t in ticks:
            row = []
            for l in range(len(self.links)):
                row.append(self.cap[l] - self.used(l, t))
            samples.append([t, row])
        return {'status': 'ok', 'rev': self.rev, 'now': self.now,
                'leases': sorted(self.live()), 'samples': samples}

    # ---------- advance ----------
    def do_advance(self, t):
        if t < self.now:
            return self.err('TIME')
        self.now = t
        expired = []
        for i, l in self.leases.items():
            if not l.dead and l.e <= t:
                l.dead = True
                l.dead_kind = 'expired'
                expired.append(i)
        self.rev += 1
        return {'status': 'ok', 'rev': self.rev, 'now': t, 'expired': sorted(expired)}

    # ---------- edit ----------
    def do_edit(self, r, changes, force):
        if r != self.rev:
            return self.stale()
        for (l, c) in changes:
            if l >= len(self.links):
                return self.err('REFERENCE')
        newcap = list(self.cap)
        for (l, c) in changes:
            newcap[l] = c
        decreased = [l for (l, c) in changes if c < self.cap[l]]
        if not force:
            # blocked check: used(l,t) > proposed capacity for some t >= now
            cand = set()
            cand.add(self.now)
            for i, lease in self.leases.items():
                if lease.dead:
                    continue
                if lease.s > self.now:
                    cand.add(lease.s)
                if lease.e > self.now:
                    cand.add(lease.e)
            for l in decreased:
                for t in sorted(cand):
                    u = self.used(l, t)
                    if u > newcap[l]:
                        return {'status': 'blocked', 'rev': self.rev, 'link': l,
                                'time': t, 'used': u, 'capacity': newcap[l]}
        cancelled = []
        if force:
            decset = set(decreased)
            for i, lease in self.leases.items():
                if lease.dead:
                    continue
                if any(lease.env.get(l, 0) > 0 for l in decset):
                    lease.dead = True
                    lease.dead_kind = 'revoked'
                    cancelled.append(i)
        self.cap = newcap
        self.rev += 1
        return {'status': 'ok', 'rev': self.rev, 'cancelled': sorted(cancelled)}

    # ---------- prepare ----------
    def prepare_payload(self, owner, w, period, parts, env, r):
        return (owner, w[0], w[1], period, tuple(sorted(parts.items())),
                tuple(sorted(env.items())), r)

    def do_prepare(self, pid, owner, w, period, parts, env, r):
        payload = self.prepare_payload(owner, w, period, parts, env, r)
        if pid in self.load_ids:
            return self.err('CONFLICT')
        if pid in self.prepares:
            rec = self.prepares[pid]
            if rec['payload'] == payload:
                return {'status': 'replay', 'id': pid, 'rev': self.rev,
                        'base_rev': rec['base_rev'], 'outcome': rec['outcome']}
            return self.err('CONFLICT')
        # new id: priority revision, references, time, window divisibility
        if r != self.rev:
            return self.stale()
        for v in parts:
            if v >= self.n:
                return self.err('REFERENCE')
        for l in env:
            if l >= len(self.links):
                return self.err('REFERENCE')
        s, e = w
        if s < self.now:
            return self.err('TIME')
        if (e - s) % period != 0:
            return self.err('WINDOW')
        # capacity check against live leases
        capw = compiler.capacity_witness(self.cap, self.leases, self.now, s, e, env)
        if capw is not None:
            (l, t, usedv, capv) = capw
            self.prepares[pid] = {'payload': payload, 'base_rev': self.rev,
                                  'outcome': 'denied'}
            return {'status': 'denied', 'id': pid, 'rev': self.rev, 'kind': 'capacity',
                    'link': l, 'time': t, 'used': usedv, 'capacity': capv}
        cut = compiler.cut_witness(self.links, env, period, parts)
        if cut is not None:
            self.prepares[pid] = {'payload': payload, 'base_rev': self.rev,
                                  'outcome': 'denied'}
            return {'status': 'denied', 'id': pid, 'rev': self.rev, 'kind': 'cut',
                    'cut': cut}
        plan = compiler.compile_plan(self.links, env, period, parts)
        self.prepares[pid] = {'payload': payload, 'base_rev': self.rev,
                              'outcome': 'prepared'}
        return {'status': 'prepared', 'id': pid, 'rev': self.rev, 'plan': plan}

    # ---------- commit ----------
    def do_commit(self, pid, owner, r):
        if pid not in self.leases and pid not in self.prepares:
            return self.err('MISSING')
        # owner check for both lease ids and prepare ids
        if pid in self.leases:
            if self.leases[pid].owner != owner:
                return self.err('OWNER')
        else:
            rec = self.prepares[pid]
            if rec['payload'][0] != owner:
                return self.err('OWNER')
        if pid in self.leases:
            lease = self.leases[pid]
            if not lease.dead and lease.e > self.now:
                return {'status': 'ok', 'id': pid, 'rev': self.rev, 'replay': True}
            return self.err('GONE')
        rec = self.prepares[pid]
        if rec['outcome'] != 'prepared':
            return self.err('DENIED')
        if r != self.rev or rec['base_rev'] != self.rev:
            return self.stale()
        payload = rec['payload']
        owner2, s, e, period, partst, envt, r2 = payload
        lease = Lease(owner2, s, e, dict(envt))
        self.leases[pid] = lease
        self.rev += 1
        return {'status': 'ok', 'id': pid, 'rev': self.rev, 'replay': False}

    # ---------- cancel ----------
    def do_cancel(self, pid, owner, r):
        if r != self.rev:
            return self.stale()
        lease = self.leases.get(pid)
        if lease is None or lease.dead or lease.e <= self.now:
            return self.err('MISSING')
        if lease.owner != owner:
            return self.err('OWNER')
        lease.dead = True
        lease.dead_kind = 'cancelled'
        self.rev += 1
        return {'status': 'ok', 'rev': self.rev, 'released': pid}

    # ---------- dispatch ----------
    def dispatch(self, cmd):
        if cmd[0] == 'about':
            return {'status': 'ok', 'protocol': 'forest-controller/3'}
        if cmd[0] == 'load':
            return self.do_load(cmd[1], cmd[2], cmd[3])
        if not self.loaded:
            return {'status': 'error', 'code': 'NOT_LOADED', 'rev': 0}
        if cmd[0] == 'audit':
            return self.do_audit(cmd[1])
        if cmd[0] == 'advance':
            return self.do_advance(cmd[1])
        if cmd[0] == 'edit':
            return self.do_edit(cmd[1], cmd[2], cmd[3])
        if cmd[0] == 'prepare':
            return self.do_prepare(cmd[1], cmd[2], cmd[3], cmd[4], cmd[5], cmd[6], cmd[7])
        if cmd[0] == 'commit':
            return self.do_commit(cmd[1], cmd[2], cmd[3])
        if cmd[0] == 'cancel':
            return self.do_cancel(cmd[1], cmd[2], cmd[3])
        raise Invalid


SERVICE = Service()


def handle(request):
    try:
        cmd = parse_command(request)
        return SERVICE.dispatch(cmd)
    except Invalid:
        return {'status': 'invalid'}
    except Exception:
        return {'status': 'invalid'}
